-- 테스트용 최소 스키마(운영 DDL과 같은 컬럼 이름). TB_USER는 API의 JPA가 만드는 테이블이라 database.sql에 없다.
CREATE TABLE IF NOT EXISTS TB_USER (USER_SEQ BIGINT AUTO_INCREMENT PRIMARY KEY, USER_EMAIL VARCHAR(100) NOT NULL, USER_PASSWORD VARCHAR(150) NOT NULL,
  USER_NIC_NAME VARCHAR(50) NOT NULL, EMAIL_CERTIFY_YN VARCHAR(1) DEFAULT 'N' NOT NULL, LOCK_YN VARCHAR(1) DEFAULT 'N' NOT NULL, LOCK_DT TIMESTAMP,
  WITHDRAWAL_YN VARCHAR(1) DEFAULT 'N' NOT NULL, WITHDRAWAL_DT TIMESTAMP, CREATE_DT TIMESTAMP, UPDATE_DT TIMESTAMP);
CREATE TABLE IF NOT EXISTS TB_LTTOT_PBLANC_COMMENT (COMMENT_SEQ BIGINT AUTO_INCREMENT PRIMARY KEY, ANNOUNCEMENT_TYPE VARCHAR(20) NOT NULL,
  HOUSE_MANAGE_NO VARCHAR(40) NOT NULL, PBLANC_NO VARCHAR(40) NOT NULL, PARENT_COMMENT_SEQ BIGINT, CONTENT TEXT NOT NULL, RECOMMEND INT DEFAULT 0 NOT NULL,
  OPPOSE INT DEFAULT 0 NOT NULL, DELETE_YN VARCHAR(1) DEFAULT 'N' NOT NULL, CREATE_USER_SEQ BIGINT NOT NULL, REG_DT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
  UPDATE_USER_SEQ BIGINT, UPDATE_DT TIMESTAMP);
CREATE TABLE IF NOT EXISTS TB_FAVORITE (USER_SEQ BIGINT NOT NULL, ANNOUNCEMENT_TYPE VARCHAR(20) NOT NULL, HOUSE_MANAGE_NO VARCHAR(40) NOT NULL, PBLANC_NO VARCHAR(40) NOT NULL,
  NOTE VARCHAR(2000) DEFAULT '' NOT NULL, CHECKLIST INT DEFAULT 0 NOT NULL, EMAIL_ENABLED BOOLEAN DEFAULT FALSE NOT NULL, REG_DT TIMESTAMP NOT NULL, STAGE TINYINT DEFAULT 0 NOT NULL,
  PRIMARY KEY (USER_SEQ, ANNOUNCEMENT_TYPE, HOUSE_MANAGE_NO, PBLANC_NO));
CREATE TABLE IF NOT EXISTS TB_PAGE_VIEW (EVENT_ID CHAR(36) PRIMARY KEY, VISITOR_ID CHAR(36) NOT NULL, SESSION_ID CHAR(36) NOT NULL, PAGE_PATH VARCHAR(100) NOT NULL,
  REFERRER_HOST VARCHAR(100), VISIT_DATE DATE NOT NULL, REG_DT TIMESTAMP NOT NULL);
CREATE TABLE IF NOT EXISTS TB_USAGE_EVENT (EVENT_ID CHAR(36) PRIMARY KEY, VISITOR_ID CHAR(36) NOT NULL, ACTION_NAME VARCHAR(20) NOT NULL, SUBJECT_ID VARCHAR(110) NOT NULL,
  VISIT_DATE DATE NOT NULL, REG_DT TIMESTAMP NOT NULL);
CREATE TABLE IF NOT EXISTS TB_PUSH_SUBSCRIPTION (ENDPOINT_HASH CHAR(64) PRIMARY KEY, ENDPOINT VARCHAR(1000) NOT NULL, P256DH VARCHAR(100) NOT NULL, AUTH VARCHAR(40) NOT NULL,
  USER_SEQ BIGINT, VISITOR_ID CHAR(36), FAVORITES_ENABLED BOOLEAN DEFAULT TRUE NOT NULL, FAVORITE_IDS TEXT, AREA_SLUGS VARCHAR(200) DEFAULT '' NOT NULL,
  REG_DT TIMESTAMP NOT NULL, UPDATED_DT TIMESTAMP NOT NULL, LAST_ATTEMPT_DATE DATE, LAST_DIGEST_DT TIMESTAMP, LAST_SUCCESS_DT TIMESTAMP);
CREATE TABLE IF NOT EXISTS TB_PRICE_GAP (ANNOUNCEMENT_ID VARCHAR(110) PRIMARY KEY, STATUS VARCHAR(12) NOT NULL, BCODE CHAR(10), DONG VARCHAR(40), AREA SMALLINT,
  SUPPLY_MANWON INT, BASIS VARCHAR(4), SCOPE VARCHAR(10), BASIS_COUNT INT, CONFIDENCE VARCHAR(8), Q1_MANWON INT, Q3_MANWON INT, MONTHS TINYINT, COMPUTED_DT TIMESTAMP NOT NULL);
-- 공고 5개 유형(목록은 UNION으로 함께 읽는다). 유형마다 접수일·주소 컬럼 이름이 다르다.
CREATE TABLE IF NOT EXISTS TB_APT_LTTOT_PBLANC_DETAIL (HOUSE_MANAGE_NO VARCHAR(40) NOT NULL, PBLANC_NO VARCHAR(40) NOT NULL, HOUSE_NM VARCHAR(200), HOUSE_SECD_NM VARCHAR(100),
  SUBSCRPT_AREA_CODE_NM VARCHAR(100), HSSPLY_ADRES VARCHAR(256), TOT_SUPLY_HSHLDCO VARCHAR(10), RCRIT_PBLANC_DE VARCHAR(10), RCEPT_BGNDE VARCHAR(10), RCEPT_ENDDE VARCHAR(10),
  PRZWNER_PRESNATN_DE VARCHAR(10), CNTRCT_CNCLS_BGNDE VARCHAR(10), MVN_PREARNGE_YM VARCHAR(6), PBLANC_URL VARCHAR(300), REG_DT TIMESTAMP DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (HOUSE_MANAGE_NO, PBLANC_NO));
CREATE TABLE IF NOT EXISTS TB_URBTY_OFCTL_LTTOT_PBLANC_DETAIL (HOUSE_MANAGE_NO VARCHAR(40) NOT NULL, PBLANC_NO VARCHAR(40) NOT NULL, HOUSE_NM VARCHAR(200), HOUSE_SECD_NM VARCHAR(100),
  SUBSCRPT_AREA_CODE_NM VARCHAR(100), HSSPLY_HSHLDCO VARCHAR(256), TOT_SUPLY_HSHLDCO VARCHAR(10), RCRIT_PBLANC_DE VARCHAR(10), SUBSCRPT_RCEPT_BGNDE VARCHAR(10), SUBSCRPT_RCEPT_ENDDE VARCHAR(10),
  PRZWNER_PRESNATN_DE VARCHAR(10), CNTRCT_CNCLS_BGNDE VARCHAR(10), MVN_PREARNGE_YM VARCHAR(6), PBLANC_URL VARCHAR(300), REG_DT TIMESTAMP DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (HOUSE_MANAGE_NO, PBLANC_NO));
CREATE TABLE IF NOT EXISTS TB_REMNDR_LTTOT_PBLANC_DETAIL (HOUSE_MANAGE_NO VARCHAR(40) NOT NULL, PBLANC_NO VARCHAR(40) NOT NULL, HOUSE_NM VARCHAR(200), HOUSE_SECD_NM VARCHAR(100),
  SUBSCRPT_AREA_CODE_NM VARCHAR(100), HSSPLY_ADRES VARCHAR(256), TOT_SUPLY_HSHLDCO VARCHAR(10), RCRIT_PBLANC_DE VARCHAR(10), SUBSCRPT_RCEPT_BGNDE VARCHAR(10), SUBSCRPT_RCEPT_ENDDE VARCHAR(10),
  PRZWNER_PRESNATN_DE VARCHAR(10), CNTRCT_CNCLS_BGNDE VARCHAR(10), MVN_PREARNGE_YM VARCHAR(6), PBLANC_URL VARCHAR(300), REG_DT TIMESTAMP DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (HOUSE_MANAGE_NO, PBLANC_NO));
CREATE TABLE IF NOT EXISTS TB_PBL_PVT_RENT_LTTOT_PBLANC_DETAIL (HOUSE_MANAGE_NO VARCHAR(40) NOT NULL, PBLANC_NO VARCHAR(40) NOT NULL, HOUSE_NM VARCHAR(200), HOUSE_SECD_NM VARCHAR(100),
  SUBSCRPT_AREA_CODE_NM VARCHAR(100), HSSPLY_ADRES VARCHAR(256), TOT_SUPLY_HSHLDCO VARCHAR(10), RCRIT_PBLANC_DE VARCHAR(10), SUBSCRPT_RCEPT_BGNDE VARCHAR(10), SUBSCRPT_RCEPT_ENDDE VARCHAR(10),
  PRZWNER_PRESNATN_DE VARCHAR(10), CNTRCT_CNCLS_BGNDE VARCHAR(10), MVN_PREARNGE_YM VARCHAR(6), PBLANC_URL VARCHAR(300), REG_DT TIMESTAMP DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (HOUSE_MANAGE_NO, PBLANC_NO));
CREATE TABLE IF NOT EXISTS TB_OPT_LTTOT_PBLANC_DETAIL (HOUSE_MANAGE_NO VARCHAR(40) NOT NULL, PBLANC_NO VARCHAR(40) NOT NULL, HOUSE_NM VARCHAR(200), HOUSE_SECD_NM VARCHAR(100),
  SUBSCRPT_AREA_CODE_NM VARCHAR(100), HSSPLY_ADRES VARCHAR(256), TOT_SUPLY_HSHLDCO VARCHAR(10), RCRIT_PBLANC_DE VARCHAR(8), SUBSCRPT_RCEPT_BGNDE VARCHAR(8), SUBSCRPT_RCEPT_ENDDE VARCHAR(8),
  PRZWNER_PRESNATN_DE VARCHAR(8), CNTRCT_CNCLS_BGNDE VARCHAR(8), MVN_PREARNGE_YM VARCHAR(6), PBLANC_URL VARCHAR(300), REG_DT TIMESTAMP DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (HOUSE_MANAGE_NO, PBLANC_NO));
CREATE TABLE IF NOT EXISTS TB_APT_LTTOT_PBLANC_MDL (HOUSE_MANAGE_NO VARCHAR(40) NOT NULL, PBLANC_NO VARCHAR(40) NOT NULL, MODEL_NO VARCHAR(2) NOT NULL, HOUSE_TY VARCHAR(17),
  SUPLY_HSHLDCO VARCHAR(10), LTTOT_TOP_AMOUNT VARCHAR(20), PRIMARY KEY (HOUSE_MANAGE_NO, PBLANC_NO, MODEL_NO));
CREATE TABLE IF NOT EXISTS TB_RATE_POLL (ANNOUNCEMENT_ID VARCHAR(110) NOT NULL, VISITOR_ID CHAR(36) NOT NULL, CHOICE TINYINT NOT NULL, REG_DT TIMESTAMP NOT NULL, PRIMARY KEY (ANNOUNCEMENT_ID, VISITOR_ID));
CREATE TABLE IF NOT EXISTS TB_ANALYTICS_EXCLUDED_VISITOR (VISITOR_ID CHAR(36) PRIMARY KEY, LABEL VARCHAR(50) NOT NULL, REG_DT TIMESTAMP NOT NULL);
CREATE TABLE IF NOT EXISTS TB_SCHEDULER_ADMIN_JOB (JOB_ID VARCHAR(36) PRIMARY KEY, JOB_KIND VARCHAR(24) NOT NULL, JOB_SOURCE VARCHAR(16) NOT NULL, START_DATE DATE NOT NULL,
  END_DATE DATE NOT NULL, STATUS VARCHAR(24) NOT NULL, TOTAL_CHUNKS INT NOT NULL, COMPLETED_CHUNKS INT DEFAULT 0 NOT NULL, CANCEL_REQUESTED BOOLEAN DEFAULT FALSE NOT NULL,
  REQUESTED_BY VARCHAR(100) NOT NULL, MESSAGE VARCHAR(1000) NOT NULL, CREATED_AT TIMESTAMP NOT NULL, STARTED_AT TIMESTAMP, FINISHED_AT TIMESTAMP, HEARTBEAT_AT TIMESTAMP NOT NULL,
  ACTIVE_SLOT INT, TRIGGER_KEY VARCHAR(64));
CREATE TABLE IF NOT EXISTS TB_COMMENT_ADMIN_HIDE (COMMENT_SEQ BIGINT PRIMARY KEY, ADMIN_NAME VARCHAR(100) NOT NULL, REG_DT TIMESTAMP NOT NULL);
